def run():
    a=read('QUALIFICATION_RESULT.json');g=read('GEOLOCATION_COMPARISON.json');q=read('QA_APPLICABILITY.json');o=read('INDEPENDENT_VALIDATION.json');sources=read('SOURCE_QUALIFICATION.json');d=read('MODLL_DOWNLOAD.json');p=read('PRESERVATION.json');v=read('VISUAL_AND_PERFORMANCE.json');mem=read('RUNTIME_MEMORY.json');t=read('full-browser-results.json')['stats'];snapshot=read('SNAPSHOT.json')
